// Build scoped presentation rules from the source pages; no source page runs at search time.
const fs = require('fs');
let playwright;
try { playwright = require('playwright'); }
catch { playwright = require('/opt/codex/runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright'); }
const { chromium } = playwright;
const files = ['PN.html','info.html','explain.html','practiceN.html','recalls.html','Clinicalnotes.html','Notes.html','ECG.html','Urgent_Care.html','face.html','Hand.html','Sha.html','Abdo.html','Spine.html','LF.html','forms.html','chatgptx.html'];
(async () => {
  const browser = await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
  const page = await browser.newPage();
  await page.setContent('<html><head></head><body></body></html>');
  await page.addScriptTag({content:fs.readFileSync('search-style-parser.js','utf8').replaceAll('export ','')});
  const output = ['/* Generated by .github/scripts/build-search-source-cards.cjs from source page presentation rules. */'];
  for (const file of files) {
    const html = fs.readFileSync(file,'utf8');
    const rootClasses = (html.match(/<html[^>]*class="([^"]*)"/)?.[1] || '').split(/\s+/);
    if (['Urgent_Care.html','face.html','Hand.html','Sha.html','Abdo.html','Spine.html','LF.html'].includes(file)) rootClasses.push('theme-urgent-care');
    const head = html.slice(0,html.indexOf('</head>'));
    const styles = [...head.matchAll(/<style[^>]*>([\s\S]*?)<\/style>|<link\b[^>]*rel="stylesheet"[^>]*>/g)].map(match => {
      if (match[1]) return match[1];
      const path = match[0].match(/href="([^"]+)"/)?.[1]?.split('?')[0];
      return path && !path.includes('://') && fs.existsSync(path) ? fs.readFileSync(path,'utf8') : '';
    });
    const compiled = await page.evaluate(({styles,file,rootClasses}) => {
      const prefix = `html:root:root .cep-search-source[data-source-file="${file.toLowerCase()}"]`;
      const cardClass = file === 'forms.html' ? '.file-item' : file === 'chatgptx.html' ? '.chatBubble' : '.note-card';
      const layouts = file==='Notes.html'?['note-grid']:file==='forms.html'?['file-grid']:file==='Clinicalnotes.html'?['notes-panel']:file==='explain.html'?['note-list']:['PN.html','info.html','practiceN.html','recalls.html'].includes(file)?['cards-container']:[];
      const allowed = /\.(?:note-card|note-tile|note-title|note-text|note-content|timestamp|note-date|note-display|note-image|note-url|file-item|view-mode|chatBubble)\b/;
      const reject = /(?:copy-feedback|copied-feedback|show-copied|\.message\.user|new-note|editing|edit-|controls|btn-|show-buttons|menu-open|actions-visible|zoomed|zoom-mode|:hover|:active|:focus|\.card-light)/;
      const split = text => { let depth=0,start=0,quote='',result=[]; for(let i=0;i<text.length;i++){const c=text[i];if(quote){if(c===quote&&text[i-1]!=='\\')quote='';continue}if(c==='"'||c==="'"){quote=c;continue}if(c==='('||c==='[')depth++;if(c===')'||c===']')depth--;if(c===','&&!depth){result.push(text.slice(start,i));start=i+1}}result.push(text.slice(start));return result; };
      const visual = /^(?:font(?:-.+)?|line-height|letter-spacing|word-spacing|color|-webkit-text-fill-color|text-(?:align|shadow|decoration.*|transform|indent)|white-space|word-break|overflow-wrap|padding(?:-.+)?|margin(?:-.+)?|border(?:-.+)?|background(?:-.+)?|box-shadow|backdrop-filter|-webkit-backdrop-filter)$/;
      const metrics = /^(?:font(?:-.+)?|line-height|letter-spacing|word-spacing|white-space|padding(?:-.+)?|margin(?:-.+)?)$/;
      const defaults = {};
      const sheets = styles.map(css=>({cssRules:readStyleRules(css)}));
      for(const sheet of sheets)for(const rule of sheet.cssRules)if(rule.declarations && /^(?:html|:root|body)$/.test(rule.header.trim()))for(const item of rule.declarations)if(item.name.startsWith('--'))defaults[item.name]=item.value;
      const fallbacks = value => value.replace(/var\((--[\w-]+)\)/g,(all,name)=>defaults[name]?`var(${name},${defaults[name]})`:all);
      function compile(rules) {
        let result='';
        for(const rule of rules){
          if(rule.rules){const inner=compile(rule.rules);if(inner)result+=`${rule.header}{${inner}}\n`;continue}
          if(!rule.declarations)continue;
          rule.selectorText=rule.header;
          const selectors=[];
          for(let selector of split(rule.selectorText)){
            selector=selector.trim();if(reject.test(selector.replace(/:not\([^)]*\)/g,'')))continue;
            const usedLayouts=[...selector.matchAll(/\.(cards-container|note-list|card-grid|notes-panel|note-grid|file-grid)\b/g)].map(m=>m[1]);
            if(usedLayouts.length&&!usedLayouts.some(name=>layouts.includes(name)))continue;
            const contextWeight=(selector.includes('.message.bot')?2:0)+(selector.match(/\.theme-[\w-]+/g)?.length ? 1 : 0)+(selector.match(/\.(?:cards-container|note-list|card-grid|notes-panel|note-grid|file-grid)\b/g)?.length ? 1 : 0);
            const bodyOnly=/^(?:html\s+)?body$/.test(selector);
            if(!bodyOnly&&!allowed.test(selector))continue;
            const themes=[...selector.matchAll(/\.theme-[\w-]+/g)].map(m=>m[0].slice(1));
            if(themes.length&&!themes.some(t=>rootClasses.includes(t)))continue;
            selector=selector.replace(/html(?::is\([^)]*\))?(?::root)?(?:\.theme-[\w-]+)?\s*/g,'').replace(/\.theme-[\w-]+/g,'').replace(/\bbody\s*/g,'').replace(/#(?:notesList|notesContainer|noteGrid|vaccineCards|filesList)\s*>?\s*/g,'').trim();
            if(bodyOnly)selector=cardClass;
            selector=selector.replace(/\.message\.bot\s+/g,'');
            selector=selector.replace(/:nth-child\(5n\s*\+\s*(\d)\)/g,(_,n)=>`[data-source-mod5="${Number(n)-1}"]`).replace(/:nth-child\(6n\)/g,'[data-source-mod6="5"]');
            selector=selector.replace(/:is\((?:\.(?:cards-container|note-list|card-grid|notes-panel|note-grid|file-grid),?\s*)+\)\s*>?\s*/g,'');
            selector=selector.replace(/\.(?:cards-container|note-list|card-grid|notes-panel|note-grid|file-grid)\s*>?\s*/g,'');
            if(selector.startsWith('>'))selector=selector.slice(1).trim();
            selectors.push(prefix+':not(.cep-source-no-context)'.repeat(contextWeight)+' '+selector);
          }
          if(!selectors.length)continue;
          const bodyOnly=split(rule.selectorText).every(item=>/^(html|body|:root)$/.test(item.trim()));
          const declarations=[];
          const pseudo=rule.selectorText.includes('::');
          for(const item of rule.declarations){
            const {name,value,important}=item;
            if(bodyOnly&&!/^(?:font(?:-.+)?|line-height)$/.test(name))continue;
            if(!visual.test(name)&&!(pseudo&&/^(content|position|inset|top|left|right|bottom|width|height|pointer-events|filter|opacity)$/.test(name)))continue;
            declarations.push(`${name}:${fallbacks(value)}${metrics.test(name)||important?' !important':''};`);
          }
          if(declarations.length)result+=selectors.join(',')+'{'+declarations.join('')+'}\n';
        }return result;
      }
      return sheets.map(sheet=>compile(sheet.cssRules)).join('');
    },{styles,file,rootClasses});
    const names = {'note-card':'cep-source-surface','note-tile':'cep-source-notebook','chatBubble':'cep-source-chat','file-item':'cep-source-form','note-title':'cep-source-title','note-text':'cep-source-text','note-content':'cep-source-content','timestamp':'cep-source-date','note-date':'cep-source-date','note-display':'cep-source-display','note-image':'cep-source-image','note-url':'cep-source-url','view-mode':'cep-source-view'};
    const scoped = compiled.replace(/\.([\w-]+)/g,(all,name)=>names[name]?'.'+names[name]:all);
    output.push(`/* ${file} */\n${scoped}`);
  }
  fs.writeFileSync('search-source-cards.css',output.join('\n'));
  await browser.close();
})().catch(error=>{console.error(error);process.exit(1)});
